function guard(request) {
  const origin = request.headers.get("origin");
  if (origin && origin !== new URL(request.url).origin) {
    return new Response("forbidden", { status: 403 });
  }
  const contentType = request.headers.get("content-type") ?? "";
  if (!contentType.includes("application/json")) {
    return new Response("unsupported media type", { status: 415 });
  }
  return null;
}

const inflight = new Map();

async function getProduct(id, load, cache) {
  const cached = await cache.get("product:" + id);
  if (cached) return cached;

  if (!inflight.has(id)) {
    inflight.set(id, load(id).finally(() => inflight.delete(id)));
  }
  const product = await inflight.get(id);
  await cache.set("product:" + id, product, { ttl: 60 + Math.random() * 30 });
  return product;
}

async function withRetry(fn, { attempts = 3, base = 100, budget = 1000 } = {}) {
  const startedAt = Date.now();
  let lastError;

  for (let i = 0; i < attempts; i += 1) {
    try { return await fn(); } catch (error) {
      lastError = error;
      if (!error.retryable) throw error;
      if (Date.now() - startedAt > budget) break;
      const backoff = Math.min(base * 2 ** i, budget);
      await new Promise((resolve) => setTimeout(resolve, backoff + Math.random() * 50));
    }
  }
  throw lastError;
}

