function paginate(items, page = 1, pageSize = 10) {
  // TODO: 规范化参数并返回分页结果
  return { items: [], page: 1, pageSize: 10, total: 0, totalPages: 1 };
}

codeChallenges.solutionCode:
function paginate(items, page = 1, pageSize = 10) {
  const list = Array.isArray(items) ? items : [];
  const size = Math.min(100, Math.max(1, Number.isInteger(pageSize) ? pageSize : 10));
  const total = list.length;
  const totalPages = Math.max(1, Math.ceil(total / size));
  const current = Math.min(totalPages, Math.max(1, Number.isInteger(page) ? page : 1));
  const start = (current - 1) * size;

  return {
    items: list.slice(start, start + size),
    page: current,
    pageSize: size,
    total,
    totalPages
  };
}

