codeChallenges.solutionCode:
function buildOrderQuery(filters) {
  const input = filters && typeof filters === "object" ? filters : {};
  const clauses = ["1=1"];
  const params = [];

  if (typeof input.status === "string" && input.status.trim()) {
    clauses.push("status = ?");
    params.push(input.status.trim());
  }
  if (Number.isFinite(input.minAmount) && input.minAmount >= 0) {
    clauses.push("amount >= ?");
    params.push(input.minAmount);
  }

  const limit = Number.isInteger(input.limit)
    ? Math.min(100, Math.max(1, input.limit))
    : 50;
  const sql = "SELECT id, status, amount FROM orders WHERE " +
    clauses.join(" AND ") + " ORDER BY id LIMIT ?";

  return { sql, params: [...params, limit] };
}

