function safeRedirect(target) {
  if (typeof target !== "string") return "/";
  const value = target.trim();
  if (!value.startsWith("/") || value.startsWith("//")) return "/";
  if (value.includes("\\\\") || /[\u0000-\u001f]/.test(value)) return "/";
  return value;
}

