  // TODO: 用 Map 顺序模拟 LRU
  return [];
}

codeChallenges.solutionCode:
function lruSimulate(capacity, operations) {
  const limit = Number.isInteger(capacity) && capacity > 0 ? capacity : 1;
  const cache = new Map();
  const result = [];

  for (const op of Array.isArray(operations) ? operations : []) {
    if (op.type === "get") {
      if (!cache.has(op.key)) {
        result.push(null);
        continue;
      }
      const value = cache.get(op.key);
      cache.delete(op.key);
      cache.set(op.key, value);
      result.push(value);
      continue;
    }
    if (op.type === "put") {
      if (cache.has(op.key)) cache.delete(op.key);
      cache.set(op.key, op.value);
      while (cache.size > limit) {
        const oldest = cache.keys().next().value;
        cache.delete(oldest);
      }
    }
  }
  return result;
}

