function retryDelays(attempts, baseMs = 100, maxMs = 1000) {
  // TODO: 生成指数退避延迟
  return [];
}

codeChallenges.solutionCode:
function retryDelays(attempts, baseMs = 100, maxMs = 1000) {
  const count = Number.isInteger(attempts) ? attempts : 0;
  if (count <= 0) return [];

  const base = Number.isFinite(baseMs) && baseMs > 0 ? baseMs : 100;
  const cap = Number.isFinite(maxMs) && maxMs >= base ? maxMs : Math.max(1000, base);
  const delays = [];
  let delay = base;

  for (let i = 0; i < count; i += 1) {
    delays.push(Math.min(delay, cap));
    delay = Math.min(delay * 2, cap);
  }
  return delays;
}
